DROP TABLE IF EXISTS `alert_rules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `alert_rules` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `description` text NOT NULL,
  `type` enum('EVENT','VEHICLE','SUPPLIER','USER') NOT NULL,
  `condition_sql` text NOT NULL COMMENT 'SQL condition pentru evaluarea regulii',
  `severity` enum('LOW','MEDIUM','HIGH','CRITICAL') NOT NULL DEFAULT 'MEDIUM',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `notification_channels` json NOT NULL COMMENT '["email", "in_app", "sms"]',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_alert_rules_active` (`is_active`),
  KEY `idx_alert_rules_type` (`type`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `alert_rules`
--

LOCK TABLES `alert_rules` WRITE;
/*!40000 ALTER TABLE `alert_rules` DISABLE KEYS */;
INSERT INTO `alert_rules` VALUES (1,'Eveniment fără asignări în 24h','Evenimentul va începe în 24 de ore dar nu are participanți asignati','EVENT','SELECT ce.* FROM calendar_events ce \n   LEFT JOIN event_assignments ea ON ce.id = ea.event_id \n   WHERE ce.start_time BETWEEN NOW() AND DATE_ADD(NOW(), INTERVAL 24 HOUR)\n   AND ce.status = \"PENDING\"\n   AND ea.id IS NULL','HIGH',1,'[\"email\", \"in_app\"]','2025-07-23 07:52:05','2025-07-23 07:52:05'),(2,'Eveniment în trecut fără status finalizat','Evenimentul a început dar nu are status finalizat','EVENT','SELECT ce.* FROM calendar_events ce \n   WHERE ce.start_time < NOW() \n   AND ce.status NOT IN (\"COMPLETED\", \"CANCELLED\")','MEDIUM',1,'[\"email\", \"in_app\"]','2025-07-23 07:52:05','2025-07-23 07:52:05'),(3,'Evenimente multiple în aceeași zi','Utilizatorul are mai mult de 5 evenimente în aceeași zi','USER','SELECT u.*, COUNT(ea.event_id) as event_count \n   FROM users u \n   JOIN event_assignments ea ON u.id = ea.user_id \n   JOIN calendar_events ce ON ea.event_id = ce.id \n   WHERE DATE(ce.start_time) = CURDATE() \n   GROUP BY u.id \n   HAVING event_count > 5','LOW',1,'[\"in_app\"]','2025-07-23 07:52:05','2025-07-23 07:52:05'),(4,'ITP expiră în 30 zile','ITP-ul vehiculului va expira în 30 de zile','VEHICLE','SELECT v.* FROM vehicles v \n   JOIN vehicle_documents vd ON v.id = vd.vehicle_id \n   WHERE vd.type = \"ITP\" \n   AND vd.expiry_date BETWEEN NOW() AND DATE_ADD(NOW(), INTERVAL 30 DAY)','MEDIUM',1,'[\"email\", \"in_app\"]','2025-07-23 07:52:05','2025-07-23 07:52:05'),(5,'RCA expiră în 30 zile','Asigurarea RCA a vehiculului va expira în 30 de zile','VEHICLE','SELECT v.* FROM vehicles v \n   JOIN vehicle_documents vd ON v.id = vd.vehicle_id \n   WHERE vd.type = \"RCA\" \n   AND vd.expiry_date BETWEEN NOW() AND DATE_ADD(NOW(), INTERVAL 30 DAY)','HIGH',1,'[\"email\", \"in_app\"]','2025-07-23 07:52:05','2025-07-23 07:52:05'),(6,'Comandă întârziată','Comanda la furnizor este în așteptare de mai mult de 7 zile','SUPPLIER','SELECT s.* FROM suppliers s \n   JOIN calendar_events ce ON ce.metadata LIKE CONCAT(\"%supplierId%:\", s.id, \"%\") \n   WHERE ce.type = \"SUPPLY_ORDER\" \n   AND ce.status = \"PENDING\" \n   AND ce.start_time < DATE_SUB(NOW(), INTERVAL 7 DAY)','MEDIUM',1,'[\"email\", \"in_app\"]','2025-07-23 07:52:05','2025-07-23 07:52:05');
/*!40000 ALTER TABLE `alert_rules` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `alerts`
--

DROP TABLE IF EXISTS `alerts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `alerts` (
  `id` int NOT NULL AUTO_INCREMENT,
  `rule_id` int NOT NULL,
  `title` varchar(255) NOT NULL,
  `message` text NOT NULL,
  `severity` enum('LOW','MEDIUM','HIGH','CRITICAL') NOT NULL,
  `status` enum('ACTIVE','ACKNOWLEDGED','RESOLVED') NOT NULL DEFAULT 'ACTIVE',
  `entity_type` enum('EVENT','VEHICLE','SUPPLIER','USER') NOT NULL,
  `entity_id` int NOT NULL,
  `user_id` int DEFAULT NULL,
  `department_id` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `acknowledged_at` timestamp NULL DEFAULT NULL,
  `resolved_at` timestamp NULL DEFAULT NULL,
  `acknowledged_by` int DEFAULT NULL,
  `resolved_by` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `department_id` (`department_id`),
  KEY `acknowledged_by` (`acknowledged_by`),
  KEY `resolved_by` (`resolved_by`),
  KEY `idx_alerts_status` (`status`),
  KEY `idx_alerts_severity` (`severity`),
  KEY `idx_alerts_entity` (`entity_type`,`entity_id`),
  KEY `idx_alerts_user` (`user_id`),
  KEY `idx_alerts_created` (`created_at`),
  KEY `idx_alerts_rule_entity` (`rule_id`,`entity_type`,`entity_id`),
  CONSTRAINT `alerts_ibfk_1` FOREIGN KEY (`rule_id`) REFERENCES `alert_rules` (`id`) ON DELETE CASCADE,
  CONSTRAINT `alerts_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `alerts_ibfk_3` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `alerts_ibfk_4` FOREIGN KEY (`acknowledged_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `alerts_ibfk_5` FOREIGN KEY (`resolved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=123 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

