--
-- Table structure for table `daily_activity_sheet`
--

DROP TABLE IF EXISTS `daily_activity_sheet`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `daily_activity_sheet` (
  `id` int NOT NULL AUTO_INCREMENT,
  `date` date NOT NULL,
  `vehicle_id` int NOT NULL,
  `driver_id` int NOT NULL,
  `trip_sheet_number` varchar(20) DEFAULT NULL,
  `operating_time_hours` decimal(5,2) DEFAULT '0.00',
  `kilometers_interior` decimal(10,2) DEFAULT '0.00',
  `kilometers_exterior` decimal(10,2) DEFAULT '0.00',
  `kilometers_equivalent` decimal(10,2) DEFAULT '0.00',
  `start_day_fuel_liters` decimal(10,2) DEFAULT '0.00',
  `liquid_fuel_added` decimal(10,2) DEFAULT '0.00',
  `numeric_fuel` decimal(10,2) DEFAULT '0.00',
  `bcf_fuel` decimal(10,2) DEFAULT '0.00',
  `equivalent_liters` decimal(10,2) DEFAULT '0.00',
  `actual_consumption_liters` decimal(10,2) DEFAULT '0.00',
  `standard_consumption_urban` decimal(5,2) DEFAULT '8.40',
  `standard_consumption_extraurban` decimal(5,2) DEFAULT '6.30',
  `end_day_fuel_liters` decimal(10,2) DEFAULT '0.00',
  `price_per_liter` decimal(10,2) DEFAULT '0.00',
  `total_value_lei` decimal(10,2) DEFAULT '0.00',
  `status` enum('DRAFT','COMPLETED') DEFAULT 'DRAFT',
  `notes` text,
  `created_by` int NOT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_daily_vehicle` (`date`,`vehicle_id`),
  KEY `created_by` (`created_by`),
  KEY `updated_by` (`updated_by`),
  KEY `idx_daily_activity_date` (`date`),
  KEY `idx_daily_activity_vehicle` (`vehicle_id`),
  KEY `idx_daily_activity_driver` (`driver_id`),
  CONSTRAINT `daily_activity_sheet_ibfk_1` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `daily_activity_sheet_ibfk_2` FOREIGN KEY (`driver_id`) REFERENCES `drivers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `daily_activity_sheet_ibfk_3` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `daily_activity_sheet_ibfk_4` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

