DROP TABLE IF EXISTS `event_stock_movements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `event_stock_movements` (
  `id` int NOT NULL AUTO_INCREMENT,
  `event_stock_operation_id` int NOT NULL,
  `stock_movement_id` int DEFAULT NULL,
  `inventory_id` int NOT NULL,
  `movement_type` enum('IN','OUT','ADJUSTMENT','TRANSFER') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `quantity_before` decimal(10,3) NOT NULL,
  `quantity_after` decimal(10,3) NOT NULL,
  `quantity_changed` decimal(10,3) NOT NULL,
  `unit_cost` decimal(10,2) DEFAULT '0.00',
  `reference_document` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `performed_by` int DEFAULT NULL,
  `performed_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `stock_movement_id` (`stock_movement_id`),
  KEY `performed_by` (`performed_by`),
  KEY `idx_event_stock_movement_operation` (`event_stock_operation_id`),
  KEY `idx_event_stock_movement_inventory` (`inventory_id`),
  KEY `idx_event_stock_movement_type` (`movement_type`),
  KEY `idx_event_stock_movement_performed` (`performed_at`),
  CONSTRAINT `event_stock_movements_ibfk_1` FOREIGN KEY (`event_stock_operation_id`) REFERENCES `event_stock_operations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `event_stock_movements_ibfk_2` FOREIGN KEY (`stock_movement_id`) REFERENCES `stock_movements` (`id`) ON DELETE SET NULL,
  CONSTRAINT `event_stock_movements_ibfk_3` FOREIGN KEY (`inventory_id`) REFERENCES `inventory` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `event_stock_movements_ibfk_4` FOREIGN KEY (`performed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chk_quantity_after_non_negative` CHECK ((`quantity_after` >= 0)),
  CONSTRAINT `chk_quantity_before_non_negative` CHECK ((`quantity_before` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
