  `product_name` varchar(255) NOT NULL,
  `supplier_id` int NOT NULL,
  `supplier_name` varchar(255) NOT NULL,
  `quantity` decimal(10,3) NOT NULL,
  `unit_price` decimal(10,2) NOT NULL DEFAULT '0.00',
  `total_price` decimal(10,2) NOT NULL DEFAULT '0.00',
  `expected_delivery_date` datetime NOT NULL,
  `status` enum('ORDERED','CONFIRMED','IN_TRANSIT','DELIVERED','CANCELLED') NOT NULL DEFAULT 'ORDERED',
  `notes` text,
  `created_by` int NOT NULL,
  `processed_by` int DEFAULT NULL,
  `processed_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `created_by` (`created_by`),
  KEY `processed_by` (`processed_by`),
  KEY `idx_event_transport_orders_event` (`event_id`),
  KEY `idx_event_transport_orders_product` (`product_id`),
  KEY `idx_event_transport_orders_supplier` (`supplier_id`),
  KEY `idx_event_transport_orders_status` (`status`),
  KEY `idx_event_transport_orders_delivery` (`expected_delivery_date`),
  CONSTRAINT `event_transport_orders_ibfk_1` FOREIGN KEY (`event_id`) REFERENCES `calendar_events` (`id`) ON DELETE CASCADE,
  CONSTRAINT `event_transport_orders_ibfk_2` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL,
  CONSTRAINT `event_transport_orders_ibfk_3` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `event_transport_orders_ibfk_4` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `event_transport_orders_ibfk_5` FOREIGN KEY (`processed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=140 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
