/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `update_inventory_on_movement` AFTER INSERT ON `stock_movements` FOR EACH ROW BEGIN
    DECLARE current_qty INT DEFAULT 0;
    
    -- Obține cantitatea curentă
    SELECT quantity INTO current_qty 
    FROM inventory 
    WHERE id = NEW.inventory_id;
    
    -- Actualizează cantitatea în funcție de tipul mișcării
    CASE NEW.type
        WHEN 'IN' THEN
            UPDATE inventory 
            SET quantity = current_qty + NEW.quantity,
                last_updated = CURRENT_TIMESTAMP
            WHERE id = NEW.inventory_id;
        WHEN 'OUT' THEN
            UPDATE inventory 
            SET quantity = current_qty - NEW.quantity,
                last_updated = CURRENT_TIMESTAMP
            WHERE id = NEW.inventory_id;
        WHEN 'ADJUSTMENT' THEN
            UPDATE inventory 
            SET quantity = NEW.quantity,
                last_updated = CURRENT_TIMESTAMP
            WHERE id = NEW.inventory_id;
    END CASE;
END */;;
DELIMITER ;
