rere\", \"transitions\": [{\"to\": \"AVIZARE\", \"action\": \"SUBMIT\"}]}, {\"code\": \"AVIZARE\", \"actor\": \"MANAGER\", \"label\": \"Avizare manager\", \"rules\": {\"autoAssign\": \"LEAST_LOADED\"}, \"transitions\": [{\"to\": \"SEMNARE\", \"action\": \"APPROVE\"}, {\"to\": \"INIT\", \"action\": \"REJECT\"}]}, {\"code\": \"SEMNARE\", \"actor\": \"SEMNATAR\", \"label\": \"Semnare electronică (mock)\", \"signature\": {\"order\": 1, \"reason\": \"Aprob cerere concediu\", \"required\": true}, \"transitions\": [{\"to\": \"ARHIVARE\", \"action\": \"SIGNED\"}]}, {\"code\": \"ARHIVARE\", \"actor\": \"SYSTEM\", \"isEnd\": true, \"label\": \"Arhivare finală\"}], \"rollback\": {\"allowed\": true, \"strategy\": \"RETURN_TO_PREVIOUS\"}, \"startStepKey\": \"INIT\"}','seed-defaults',1,1,'2025-12-22 14:42:39');
